def max_value_on_paths(N, grid_values):
    leading_path = np.full((N, N), -float('inf'))
    trailing_path = np.full((N, N), -float('inf'))
    leading_path[0, 0] = grid_values[0][2]
    trailing_path[N-1, N-1] = grid_values[-1][-1]

    for idx, (i, j, value) in enumerate(grid_values):
        if idx != 0 and idx != -1:
            leading_path[i-1][j] = np.max([leading_path[i][j], leading_path[i-1][j]])
            trailing_path[i][j-1] = np.max([trailing_path[i][j], trailing_path[i][j-1]])

    result = 0
    # Calculate maximum sum of two paths from top-left corner to bottom-right corner
    for i in range(N):
        for j in range(N):
            result = np.max([result, leading_path[i][j] + trailing_path[i][j]])

    return result

def find_number_combinations():
    """
    Generate all unique combinations of three numbers, each formed from the digits 1 to 9 without repetition,
    such that the second number is twice the first and the third is three times the first.

    Returns:
        list of tuples: A sorted list of tuples, where each tuple contains three integers representing the
                        valid number combinations in ascending order based on the first number.
    """
    valid_combinations = []
    # Generate all combinations of three digits
    for first_digit in range(1, 10):
        for second_digit in range(1, 10):
            if second_digit == 2 * first_digit:
                for third_digit in range(1, 10):
                    if third_digit == 3 * first_digit:
                        combination = (first_digit, second_digit, third_digit)
                        valid_combinations.append(combination)

    # Convert the list of tuples to a sorted list
    valid_combinations.sort()
    return valid_combinations

