def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Create a 2D array to store the maximum importance values for each item and budget
    dp = [[0 for _ in range(n + 1)] for _ in range(m + 1)]

    # Fill the dp array using the bottom-up approach
    for i in range(1, m + 1):
        price, importance = items[i - 1]
        for j in range(1, n + 1):
            if price <= j:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - price] + importance)
            else:
                dp[i][j] = dp[i - 1][j]

    # The maximum happiness is stored in the bottom-right corner of the dp array
    return dp[m][n]

def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Initialize a 2D array to store the maximum happiness for each budget and item
    happiness_matrix = [[0] * (m + 1) for _ in range(n + 1)]

    # Iterate through each item and budget
    for i, (price, importance) in enumerate(items, start=1):
        for j in range(n + 1):
            # If the item can be bought within the current budget, update the happiness matrix
            if price <= j:
                happiness_matrix[j][i] = max(happiness_matrix[j], happiness_matrix[j - price][i - 1] + importance)
            else:
                # If the item cannot be bought, keep the previous happiness value
                happiness_matrix[j][i] = happiness_matrix[j][i - 1]

    # The maximum happiness value that can be achieved without exceeding the budget
    return happiness_matrix[n][m]

def max_energy(beads):
    N = len(beads)
    dp = [[0 for i in range(N)] for j in range(N)]

    for l in range(N+1):
        for i in range(N-l):
            j = i + l - 1

            if l == 1:
                dp[i][j] = beads[i]
            else:
                max_energy = 0
                for k in range(i, j):
                    max_energy = max(max_energy, dp[i][k] * beads[k] * beads[j])
                dp[i][j] = max_energy

    return dp[0][N-1]

def max_energy(beads):
    n = len(beads)
    dp = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if beads[i] == beads[j]:
                dp[i][j] = dp[i + 1][j - 1]
            elif i == j:
                dp[i][j] = beads[i]
            else:
                dp[i][j] = max(dp[i][k] + dp[k + 1][j] for k in range(i + 1, j))

    return dp[0][n - 1]

def max_energy(beads):
    # Base case: if there are no beads, the maximum energy is 0
    if not beads:
        return 0

    # Base case: if there is only one bead, the maximum energy is its head value times its tail value
    if len(beads) == 1:
        return beads[0] * beads[0]

    # Initialize the maximum energy to 0
    max_energy = 0

    # Iterate over all possible subsequences of beads
    for start in range(len(beads)):
        for end in range(start, len(beads)):
            # Check if the subsequence is valid (i.e., the head value of the first bead is equal to the tail value of the last bead)
            if beads[start] == beads[end]:
                # Compute the energy of the subsequence
                energy = beads[start] * beads[end] * beads[start]
                # Update the maximum energy if the current energy is greater
                max_energy = max(max_energy, energy)

    return max_energy

def max_energy(beads):
    n = len(beads)
    if n < 2:
        return 0

    # Initialize dynamic programming table
    dp = [0] * n
    dp[0] = beads[0]

    # Fill the dp table
    for i in range(1, n):
        dp[i] = max(dp[i-1], dp[i-2] * beads[i])

    # Since the necklace is circular, the last bead can be considered as the first
    return max(dp[n-1], dp[n-2] * beads[0])

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    if n == 0:
        return '0'

    result = ''
    for degree in range(n, 0, -1):
        coeff = coeffs[degree - 1]
        if coeff == 0:
            continue
        term = '{:+}'.format(abs(coeff)) if coeff != 1 else ''
        if degree > 1:
            term += f'x^{degree}'
        elif degree == 1:
            term += 'x'
        result = term + (' + ' if result else '') + result

    # Add the constant term
    result = f'{coeffs[-1]} + {result}' if coeffs[-1] != 0 else result

    return result.strip()

