    game_results = []

    # Iterate through each point in the sequence
    for point in point_list:
        # Update the score based on the current point
        if point == "W":
            player_score += 1
        elif point == "L":
            opponent_score += 1

        # Check if either player has exceeded the system's required points
        if player_score >= system and opponent_score < system - 1:
            game_results.append("{}:{}".format(player_score, system))
            break
        elif opponent_score >= system and player_score < system - 1:
            game_results.append("{}:{}".format(system, opponent_score))
            break

        # Check if either player has achieved a double-point lead
        if player_score >= opponent_score + 2 and opponent_score < system - 1:
            game_results.append("{}:{}".format(player_score, (system - 1) + (2 - opponent_score)))
            break
        elif opponent_score >= player_score + 2 and player_score < system - 1:
            game_results.append("({}:{})".format((system - 1) + (2 - player_score), opponent_score))
            break

    # Add the final score of the game if not yet added
    if len(game_results):
        return game_results
    else:
        return ["{}:{}".format(player_score, system)]

def calculate_score(system: int, points: str) -> list:
    scores = []
    player_score = 0
    opponent_score = 0

    for point in points:
        if point == 'W':
            player_score += 1
        else:
            opponent_score += 1

        if point == 'L' and (2 * player_score - opponent_score) >= system:
            scores.append(f"{player_score}:{opponent_score}")

        if point == 'W' and (2 * player_score - opponent_score) >= system:
            scores.append(f"{player_score}:{opponent_score}")

        if opponent_score >= system:
            break

    return scores

def catalan_number(n: int) -> int:
    # Base cases
    if n <= 1:
        return 1

    # Initialize the dp array
    dp = [0] * (n + 1)
    dp[0] = 1  # Catalan number for 0th position is 1

    # Compute the Catalan numbers using dynamic programming
    for i in range(2, n + 1):
        for j in range(0, i):
            dp[i] += dp[j] * dp[i - j - 1]

    # Return the nth Catalan number
    return dp[n]

