def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Initialize a 2D list to store the maximum value that can be picked with a given time
    dp = [[0] * (T + 1) for _ in range(M + 1)]

    for i in range(1, M + 1):
        time, value = herbs[i - 1]
        for t in range(1, T + 1):
            if t >= time:
                dp[i][t] = max(dp[i - 1][t], dp[i - 1][t - time] + value)
            else:
                dp[i][t] = dp[i - 1][t]

    # Find the maximum value that can be picked with the given time limit
    return dp[M][T]

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    if len(herbs) == 0:
        return 0

    # Sort herbs by value in descending order to prioritize high-value herbs first
    herbs.sort(key=lambda x: x[1], reverse=True)

    # Initialize DP table to store the maximum value of herbs that can be picked up to a given time
    dp = [0] * (T + 1)

    # Iterate over each herb and update the DP table
    for time, value in herbs:
        for i in range(T, time - 1, -1):
            dp[i] = max(dp[i], dp[i - time] + value)

    # The maximum value of herbs that can be picked up to the given time limit is dp[T]
    return dp[T]

def max_herb_value(T, M, herbs):
    # Initialize a list to store the maximum value each herb can have at time i
    dp = [0] * (T + 1)

    # Iterate through each herb
    for herb, val in herbs:
        # Iterate through each time in reverse order to maximize the value
        for i in range(T, herb - 1, -1):
            dp[i] = max(dp[i], dp[i - herb] + val)

    # The maximum value that can be picked within the time limit is dp[T]
    return dp[T]

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    values = [herb[1] for herb in herbs]
    times = [herb[0] for herb in herbs]

    # If the total herb time exceeds the time limit, the maximum value is 0
    if sum(times) > T:
        return 0

    # Initialize a 2D DP table
    dp = [[0] * (T + 1) for _ in range(M + 1)]

    # Fill the DP table
    for i in range(1, M + 1):
        for j in range(T + 1):
            if times[i - 1] <= j:
                dp[i][j] = max(values[i - 1] + dp[i - 1][j - times[i - 1]], dp[i - 1][j])
            else:
                dp[i][j] = dp[i - 1][j]

    # The max value is in the last cell of the DP table
    return dp[M][T]

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Create a table 'dp' with n+1 rows and V+1 cols to store the maximum volume that can be occupied
    dp = [[0] * (V + 1) for _ in range(n + 1)]

    # Iterate through each item and each possible volume from 1 to V
    for i in range(1, n + 1):
        for j in range(1, V + 1):
            # Include the current item in the maximum volume if the current volume is sufficient
            if volumes[i - 1] <= j:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - volumes[i - 1]] + volumes[i - 1])
            else:
                dp[i][j] = dp[i - 1][j]

    # The minimum remaining space is the difference between the box's total capacity and the maximum occupied volume
    min_remaining_space = V - dp[n][V]

    return min_remaining_space

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Create a table to keep track of the maximum occupied volume for each subset of items
    dp = [0] * (V + 1)

    # Iterate over each item
    for i in range(n):
        # Update the dp table for each capacity from V down to volumes[i]
        for j in range(V, volumes[i] - 1, -1):
            dp[j] = max(dp[j], dp[j - volumes[i]] + volumes[i])

    # The minimum remaining space is the difference between the box's capacity and the maximum occupied volume
    return V - dp[V]

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize the dp table where dp[i][j] represents the maximum volume that can be occupied with the first i items,
    # using the last j bits of the binary representation
    dp = [[0] * (1 << n) for _ in range(V + 1)]

    # Base case: The maximum volume is 0 if no items are considered
    for i in range(1 << n):
        dp[0][i] = 0

    # Fill the dp table
    for volume in range(1, V + 1):
        for i in range(1, n + 1):
            if volume < volumes[i - 1]:
                dp[volume][i] = dp[volume][i - 1]
            else:
                dp[volume][i] = max(dp[volume][i - 1], dp[volume - volumes[i - 1]][i - 1] + volumes[i - 1])

    # The minimum remaining space is V minus the maximum occupied volume
    return V - dp[V][1 << n - 1]

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    dp = [0] * (V + 1)

    for i in range(n):
        for j in range(V, volumes[i] - 1, -1):
            dp[j] = max(dp[j], dp[j - volumes[i]] + volumes[i])

    remaining_space = V - dp[V]
    return remaining_space

def calculate_arrangements(n, m, a):
    MOD = 10**6 + 7
    comb = [0] * (m+1)
    comb[0] = comb[1] = 1
    for i in range(2, m+1):
        comb[i] = (comb[i-1] + comb[i-2]) % MOD
    ans = 1
    for i in range(n):
        if a[i] > m:
            return 0
        ans = (ans * comb[m] % MOD) * inv(comb[a[i]], MOD)
    return ans

