def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def cipher_decrypt(text, shift):
        result = ''
        for char in text:
            if char.isalpha():
                alphabet = 'abcdefghijklmnopqrstuvwxyz' if char.islower() else 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
                shift_amount = shift % 26
                position = (alphabet.index(char.lower()) - shift_amount) % 26
                result += alphabet[position].upper() if char.isupper() else alphabet[position]
            else:
                result += char
        return result

    shift = sum(ord(c) - ord(k) for c, k in zip(ciphertext, itertools.cycle(key)))
    return cipher_decrypt(ciphertext, shift)

def mod_inverse(a, b):
    if __gcd(a, b) != 1:
        return None

    # To find modular multiplicative inverse, we use the extended Euclidean algorithm
    x, y, gcd = extended_euclidean(a, b)

    # If gcd(a, b) is 1, x is the modular multiplicative inverse
    if gcd == 1:
        return x % b
    else:
        return None

def mod_inverse(a, b):
    if b == 0:
        return None  # Inverse does not exist for 0

    x, y, x1, y1 = 1, 0, 0, 1

    while b != 0:
        q = a // b
        a, b = b, a % b
        x, x1 = x1 - q * x, x
        y, y1 = y1 - q * y, y

    if x < 0:
        x += b

    return x

