def next_permutation(perm):
    if not perm:
        return False

    # Find the first index i from the end such that perm[i] < perm[i + 1]
    i = -1
    for j in range(len(perm) - 2, -1, -1):
        if perm[j] < perm[j + 1]:
            i = j
            break

    if i == -1:
        return False    # Last permutation, no next permutation

    # Find the smallest element in the remaining portion of the list that is greater than perm[i]
    j = len(perm) - 1
    while perm[j] <= perm[i]:
        j -= 1

    # Swap perm[i] and perm[j]
    perm[i], perm[j] = perm[j], perm[i]

    # Reverse the remaining portion of the list
    perm[i + 1:] = perm[i + 1:][::-1]

    return True

def next_permutation(perm: list) -> bool:
    n = len(perm)
    for i in range(n-2, -1, -1):
        if perm[i] < perm[i+1]:
            # Find the smallest element in the sublist from i+1 to n that is greater than perm[i]
            for j in range(n-1, i, -1):
                if perm[j] > perm[i]:
                    # Swap perm[i] and perm[j]
                    perm[i], perm[j] = perm[j], perm[i]
                    # Reverse the order of the elements from i+1 to n
                    perm[i+1:] = perm[i+1:][::-1]
                    return True

    # If no such i is found, the permutation is the last and there is no next permutation
    return False

